// Load skills with the built Nexus SkillManager as Nexus would at startup (HOME is set by the caller).
// argv: <nexus cli dist dir> <workspace> [trust]
import path from "node:path";
const [dist, ws, trust] = process.argv.slice(2);
const { SkillManager } = await import(path.join(dist, "skills.js"));
const wt = await import(path.join(dist, "workspace_trust.js"));
if (trust === "trust") wt.setWorkspaceTrusted(ws, true);
const sm = new SkillManager(ws); // trust decided by Nexus's own workspace-trust store
const out = {
  trusted: sm.listSkills().map((s) => ({ name: s.name, ws: s.isWorkspaceSkill, path: path.relative(process.env.HOME, s.path).startsWith("..") ? path.relative(ws, s.path) : "~/" + path.relative(process.env.HOME, s.path), desc: s.description.slice(0, 50), bodyChars: s.content.length })),
  untrusted: sm.listUntrustedSkills().map((s) => s.name),
  badDescriptions: sm.listSkills().filter((s) => !s.description || /^[|>][+-]?$/.test(s.description) || s.description === "Specialized skill instructions").map((s) => s.name),
};
console.log(JSON.stringify(out, null, 1));

